import ast,pathlib,sys; root=pathlib.Path(sys.argv[1]); bad=[]; n=0; 
for p in root.rglob('*.py'):
  if any(x in p.parts for x in ('.git','.venv','venv','node_modules','vendor','build','dist')): continue
  n+=1
  try: ast.parse(p.read_text(encoding='utf-8',errors='strict'), filename=str(p))
  except Exception as e: bad.append(f'{p}: {type(e).__name__}: {e}')
print(f'python_files={n} failures={len(bad)}'); print('\n'.join(bad[:100])); sys.exit(1 if bad else 0)
